/**
 * The full-dMAT mock — the one sitting that runs both modules.
 *
 * Four properties, each easy to break without noticing:
 *
 *  · Its Core questions share nothing with the four frozen Core mocks. A
 *    candidate who has worked through those must not meet the same item again
 *    in what is sold as a full-length sitting.
 *  · The four Core mocks are untouched by its existence. They are generated by
 *    a different script against a different file, and this is the assertion
 *    that keeps it that way.
 *  · The General Academic half is a FIXED list of pack ids. Resolving it as
 *    "every active pack" would make the mock change whenever a pack is added,
 *    and a mock whose content moves is not a mock.
 *  · The timings are the official ones.
 */
import { test, describe } from 'node:test'
import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'

const read = (p) => JSON.parse(readFileSync(new URL(`../../${p}`, import.meta.url), 'utf8'))

const full = read('content/access/full-mock.json')
const coreMocks = read('content/access/core-mocks.json')
const SECTIONS = ['figure-sequences', 'mathematical-equations', 'latin-squares']

describe('the full dMAT mock — Core half', () => {
  test('three subtests of twenty, sixty questions in all', () => {
    assert.equal(full.questionsPerSection, 20)
    for (const section of SECTIONS) {
      assert.equal(
        full.sections[section].length,
        20,
        `${section} does not hold 20 questions`,
      )
    }
    const all = SECTIONS.flatMap((s) => full.sections[s])
    assert.equal(all.length, 60)
    assert.equal(new Set(all).size, 60, 'a question appears twice in the sitting')
  })

  test('it shares no question with any of the four Core mocks', () => {
    const used = new Set()
    for (const set of coreMocks.sets) {
      for (const ids of Object.values(set.sections)) for (const id of ids) used.add(id)
    }
    const clashes = SECTIONS.flatMap((s) => full.sections[s]).filter((id) => used.has(id))
    assert.deepEqual(clashes, [], 'the full mock reuses questions from the four Core mocks')
  })

  test('every question it names is active and really exists', () => {
    for (const section of SECTIONS) {
      const bank = new Map(
        read(`content/sections/${section}/questions.json`).map((q) => [q.id, q]),
      )
      for (const id of full.sections[section]) {
        const q = bank.get(id)
        assert.ok(q, `${id} is not in the ${section} bank`)
        assert.ok(!q.meta?.quarantined, `${id} is quarantined and must reach no pool`)
        assert.equal(q.section, section, `${id} is filed under the wrong section`)
      }
    }
  })

  test('the four Core mocks are untouched', () => {
    assert.equal(coreMocks.sets.length, 4)
    assert.equal(coreMocks.questionsPerSection, 20)
    const all = coreMocks.sets.flatMap((s) => Object.values(s.sections).flat())
    assert.equal(all.length, 240)
    assert.equal(new Set(all).size, 240)
  })
})

describe('the full dMAT mock — General Academic half', () => {
  test('it names a fixed list of packs, not whatever happens to be active', () => {
    assert.ok(Array.isArray(full.gamPackIds))
    assert.ok(full.gamPackIds.length > 0, 'the sitting has no General Academic half')
    assert.equal(new Set(full.gamPackIds).size, full.gamPackIds.length, 'a pack is listed twice')
  })

  test('every pack resolves, is not retired, and the count is right', () => {
    let counted = 0
    for (const id of full.gamPackIds) {
      const file = read(`content/gam/packs/${id}.json`)
      assert.equal(file.pack.id, id)
      assert.notEqual(
        file.pack.provenance.reviewStatus,
        'rejected',
        `${id} is retired and must not sit in a mock`,
      )
      counted += file.questions.length
    }
    assert.equal(counted, full.gamQuestionCount, 'gamQuestionCount disagrees with the packs')
    // The ten questions written for the exam-alignment pass of 22 November 2026.
    assert.equal(counted, 10)
  })

  test('every General Academic question keeps the official answer format', () => {
    for (const id of full.gamPackIds) {
      const file = read(`content/gam/packs/${id}.json`)
      for (const q of file.questions) {
        assert.equal(q.options.length, 4, `${q.id} does not offer exactly four options`)
        assert.ok(
          q.options.some((o) => o.id === q.correctOptionId),
          `${q.id} has a key that is not one of its options`,
        )
      }
    }
  })
})

describe('the full dMAT mock — timing', () => {
  test('the stage lengths are the official ones', () => {
    // GAM PDF pp. 8, 18, 25 — each Core subtest is 25 minutes / 20 items.
    assert.equal(full.minutesPerCoreStage, 25)
    // GAM PDF p. 34 — the Subject Module runs 90 minutes in total.
    assert.equal(full.gamMinutes, 90)
    // GAM PDF p. 6 — "about three hours with a break of 30 minutes".
    assert.equal(full.breakMinutes, 30)
  })

  test('the parts add up to the 195 minutes the repository computes', () => {
    // The known discrepancy, recorded rather than resolved: the PDF says "about
    // three hours", d-mat.de says three and a half. 75 + 30 + 90 is what the
    // parts actually come to, and it is what this sitting runs.
    const total = full.minutesPerCoreStage * 3 + full.breakMinutes + full.gamMinutes
    assert.equal(total, 195)
  })
})
